"""Validate eight primary-source LOFTEE role drafts without applying them to the current catalog."""
import argparse,gzip,hashlib,json,xml.etree.ElementTree as ET
from pathlib import Path
from setup_deseq2_reference import ROOT,pin,save
from collect_omics_review import paragraphs,validate_supporting_evidence,tool_matches
from smr_catalog import load_catalog_registry

ROLES={
 'P023':('Selected high-confidence loss-of-function sites using Ensembl VEP with LOFTEE for the All of Us rare-variant burden analysis; restricted analyzed variants to MAF <1%.','Exact VEP/LOFTEE versions and reference resources are unspecified. Cohort/MCH filtering, covariates and subsequent burden testing are separate study operations; no rare-variant threshold or cohort definition is inferred by LOFTEE.',None,'high-confidence-site-selection'),
 'P106':('Annotated variants pooled from UKB and All of Us with VEP105 and reported LOFTEE GRCh38 v.1.04, grouping them as loss-of-function, missense or synonymous before constructing the LD matrix.','The cited BRaVa pipeline is an annotation resource, not a specified immutable container digest. Its current resource revisions do not identify the paper execution. No confidence cutoff or transcript selection absent from this paragraph is invented. Cohort-specific GRM and association models remain separate.','1.04','pooled-cohort-functional-annotation'),
 'P142':('Used high-confidence LOFTEE loss-of-function predictions in the coding_filter1 rare-variant mask, with separate qualifying missense variants; retained the coding set when adding regulatory variants for coding_noncoding_filter1.','GENCODE v29, MAF <0.01, cumulative MAC >=20 and aggregation-wise Bonferroni testing are paper choices. MetaSV, GeneHancer, Fathmm-XF and regulatory annotations are additional mask components. Exact LOFTEE release/resources and newly executed versus supplied annotation provenance are unspecified.',None,'high-confidence-gene-mask-component'),
 'P159':('Included LOFTEE with VEP94.5 and classified canonical-transcript variants using high-confidence LoF calls; placed low-confidence LoF calls in the separate functional-variant category.','Preserve the paper\'s LoF consequence list, including stop_lost and transcript_ablation, while still requiring the reported HC annotation; do not manufacture an HC call from consequence alone. LOFTEE release is unspecified. SpliceAI cutoffs and canonical-transcript classification are separate study rules; LC is not universally discarded.',None,'canonical-transcript-HC-LC-classification'),
 'P194':('Used LOFTEE v.1.04_GRCh38 with VEP105 to annotate exome loss-of-function confidence, selecting MANE Select protein-coding transcripts with GENCODE v39 canonical fallback for downstream variant categories.','dbNSFP4.3, CADD1.6, REVEL and SpliceAI1.3 remain distinct resources/methods. The cited floating pipeline now advertises changed resources; do not silently substitute dbNSFP5.4a/CADD1.7 or claim its current container is the paper image. Transcript selection occurs after annotation and must remain explicit.','1.04_GRCh38','MANE-with-canonical-fallback-confidence-annotation'),
 'P204':('Filtered low-confidence LOFTEE calls from protein-truncating variants annotated with VEP109.3, then retained the most severe consequence per variant-gene pair.','The paper considers consequences from any transcript; do not replace this with canonical/MANE-only selection. Its PTV class contains splice acceptor/donor, stop-gained and frameshift variants, while stop-lost is in its missense class. LOFTEE version/resources are unreported; read/genotype filtering and PolyPhen/SIFT classes are separate.',None,'any-transcript-PTV-low-confidence-filter'),
 'P210':('Used LOFTEE v1.04 with VEP105 to classify protein-truncating variants as high- or low-confidence loss-of-function calls before hierarchical variant categorization.','MANE Select is preferred with GENCODE v39 canonical fallback. dbNSFP4.3 CADD/REVEL and separate SpliceAI1.3 annotations are additional inputs. Confidence alone does not reproduce the hierarchy, paper burden groups or association tests. The source reports1.04; a precise paper plugin commit/image digest is not supplied.','1.04','HC-LC-confidence-for-hierarchical-categories'),
 'P220':('Used LOFTEE v1.04 GRCh38 with VEP105 for exome loss-of-function confidence before defining gene-testing categories, using MANE Select protein-coding transcripts and GENCODE v39 canonical fallback.','Keep dbNSFP4.3, CADD1.6, REVEL and SpliceAI1.3 distinct from LOFTEE. The later combined high-confidence pLoF/damaging definition and rare-variant gene tests use multiple methods; LOFTEE alone does not implement those masks or tests. Current changes to the cited floating pipeline do not establish the original execution profile.','1.04 GRCh38','MANE-with-canonical-fallback-gene-category-input')}


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--out',required=True,type=Path);a=p.parse_args();out=a.out.resolve();assert out.is_relative_to(ROOT/'build/literature-review/loftee-runtime') and not out.exists();out.mkdir(parents=True);data=ROOT/'docs/literature/omics-2023-2026';paper_path=data/'papers.json';review_path=ROOT/'tools/literature/reviewed-uses.json';before={p.relative_to(ROOT).as_posix():pin(p) for p in [paper_path,review_path,data/'tool-inventory.json',data/'summary.json']};papers=json.loads(paper_path.read_bytes());registry={r['id']:r for r in load_catalog_registry(ROOT)};drafts=[]
    for paper in papers:
        if paper['paper_id'] not in ROLES:continue
        tool=next(t for t in paper['tools'] if t['tool_id']=='loftee');raw=gzip.decompress((ROOT/'build/literature-review/xml'/(paper['pmcid']+'.xml.gz')).read_bytes());assert hashlib.sha256(raw).hexdigest()==paper['xml_sha256'];root=ET.fromstring(raw);assert next(e.text for e in root.findall('front/article-meta/article-id') if e.get('pub-id-type')=='doi').lower()==paper['doi'].lower();ps=paragraphs(root);primary=next(s for s in ps if s['paragraph_index']==tool['evidence_paragraph_index']);digest=hashlib.sha256(primary['text'].encode('utf8')).hexdigest();assert digest==tool['evidence_paragraph_sha256'];summary,scope,version,context=ROLES[paper['paper_id']];review=dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='loftee',evidence_paragraph_sha256=digest,use_summary=summary,implementation_scope_note=scope,version_reported_near_name=version,usage_context=context)
        if paper['paper_id']=='P220':
            support=next(s for s in ps if s['paragraph_index']==58);review['supporting_evidence']=[dict(paragraph_index=58,section=support['section'],paragraph_sha256=hashlib.sha256(support['text'].encode('utf8')).hexdigest())]
        validate_supporting_evidence(ps,[review],registry);matches=tool_matches(ps,[registry['loftee']],{'loftee':digest});assert len(matches)==1 and matches[0]['evidence_paragraph_index']==primary['paragraph_index'];drafts.append(dict(paper_id=paper['paper_id'],primary_paragraph=primary['paragraph_index'],section=primary['section'],review=review,xml_sha256=paper['xml_sha256']))
    assert len(drafts)==8 and {d['paper_id'] for d in drafts}==set(ROLES);target=ROOT/'tools/literature/loftee-use-reviews.json';raw=(json.dumps(drafts,ensure_ascii=False,indent=2)+'\n').encode('utf8');assert not target.exists() or target.read_bytes()==raw;target.write_bytes(raw);assert all(pin(ROOT/n)==v for n,v in before.items());save(out/'COMPLETED.json',dict(status='validated-eight-unapplied-LOFTEE-primary-role-drafts',draft=pin(target),papers=8,supporting_pointers=1,prior_reviews=944,current_catalog_unchanged=before,applied=False,source_pins={Path(__file__).resolve().relative_to(ROOT).as_posix():pin(Path(__file__))},implementation_credit=False,whole_goal_complete=False));print('Validated8 unapplied primary-source LOFTEE roles; current catalog and944 reviews unchanged')


if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable primary-source/catalog checks')
    main()
